∀ {B P A D : Type} [inst : DecidableEq.{1} B] (branches : DefiKernel.Nary.Branches B P A D)
  (schedule : DefiKernel.Nary.Schedule B) (b : B) (rest : List.{0} B),
  @Ne.{1} Nat (@List.count.{0} B (@instBEqOfDecidableEq.{0} B inst) b schedule)
      (@List.length.{0} (DefiKernel.Composition.Invocation P A D) (branches b)) →
    @Eq.{u_1 + 1} (Except.{0, u_1} (DefiKernel.Nary.ScheduleMismatch B) PUnit.{u_1 + 1})
      (@DefiKernel.Nary.checkCountsFrom.{u_1} B P A D inst branches schedule (@List.cons.{0} B b rest))
      (@Except.error.{0, u_1} (DefiKernel.Nary.ScheduleMismatch B) PUnit.{u_1 + 1}
        (@DefiKernel.Nary.ScheduleMismatch.mk B b
          (@List.length.{0} (DefiKernel.Composition.Invocation P A D) (branches b))
          (@List.count.{0} B (@instBEqOfDecidableEq.{0} B inst) b schedule)))

∀ {B P A D : Type} [inst : DecidableEq.{1} B] [inst_1 : DecidableEq.{1} P] [inst_2 : DecidableEq.{1} A]
  [inst_3 : DecidableEq.{1} D] [inst_4 : Fintype.{0} P] [inst_5 : Fintype.{0} A] [inst_6 : Fintype.{0} D]
  {cfg : DefiKernel.Composition.Config P A D} {boundaries : DefiKernel.Nary.Boundaries B P A D}
  {branches : DefiKernel.Nary.Branches B P A D} {initial : DefiKernel.Composition.World P A D}
  {m : DefiKernel.Nary.Machine B P A D},
  @DefiKernel.Nary.Reachable B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 cfg boundaries branches initial m →
    ∀ (invariant : B → DefiKernel.Nary.LedgerPredicate P A D)
      (guarantee rely : B → DefiKernel.Nary.LedgerRelation P A D),
      (∀ (b : B), invariant b (@DefiKernel.Typed.ExecutionResult.state P A D initial)) →
        @DefiKernel.Nary.LocalObligation B P A D inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 cfg boundaries branches
            invariant guarantee →
          @DefiKernel.Nary.CrossInclusion B P A D guarantee rely →
            @DefiKernel.Nary.Stable B P A D invariant rely →
              ∀ (schedule : DefiKernel.Nary.Schedule B) (b : B),
                invariant b
                  (@DefiKernel.Typed.ExecutionResult.state P A D
                    (@DefiKernel.Nary.Machine.world B P A D
                      (@DefiKernel.Nary.continueRun B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 cfg
                        boundaries branches m schedule)))

∀ {B P A D : Type} [inst : DecidableEq.{1} B] [inst_1 : DecidableEq.{1} P] [inst_2 : DecidableEq.{1} A]
  [inst_3 : DecidableEq.{1} D] [inst_4 : Fintype.{0} P] [inst_5 : Fintype.{0} A] [inst_6 : Fintype.{0} D] {Q : Type}
  (cfg : DefiKernel.Composition.Config P A D) (boundaries : DefiKernel.Nary.Boundaries B P A D)
  (branches : DefiKernel.Nary.Branches B P A D) (update : Q → DefiKernel.Nary.MonitorInput B P A D → Q)
  (entry : Prod.{0, 0} Q (DefiKernel.Nary.Machine B P A D)) (K : DefiKernel.Nary.JointInvariant Q B P A D)
  (invariant : B → DefiKernel.Typed.State P A D → Prop)
  (guarantee rely : B → DefiKernel.Typed.State P A D → DefiKernel.Typed.State P A D → Prop)
  (assumption : DefiKernel.Nary.AssumptionFamily B Q P A D) (external : DefiKernel.Nary.ExternalFamily B Q P A D),
  K (@Prod.fst.{0, 0} Q (DefiKernel.Nary.Machine B P A D) entry)
      (@Prod.snd.{0, 0} Q (DefiKernel.Nary.Machine B P A D) entry) →
    @DefiKernel.Nary.InvariantDerivation B P A D Q K invariant →
      @DefiKernel.Nary.AssumptionDerivation B P A D Q K assumption external →
        @DefiKernel.Nary.PresentExternal B P A D Q K external →
          @DefiKernel.Nary.SelectedSuccessGuarantee B P A D inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 Q cfg boundaries
              branches invariant guarantee assumption →
            @DefiKernel.Nary.GuaranteeInclusion B P A D guarantee rely →
              @DefiKernel.Nary.RelyStable B P A D invariant rely →
                @DefiKernel.Nary.SkipUpdateObligation B P A D inst Q cfg boundaries branches update K →
                  @DefiKernel.Nary.RefusalUpdateObligation B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 Q cfg
                      boundaries branches update K →
                    @DefiKernel.Nary.SuccessUpdateObligation B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 Q
                        cfg boundaries branches update K invariant guarantee assumption →
                      ∀ (b : B),
                        K
                          (@Prod.fst.{0, 0} Q (DefiKernel.Nary.Machine B P A D)
                            (@DefiKernel.Nary.advanceMonitored B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 Q
                              cfg boundaries branches update entry b))
                          (@Prod.snd.{0, 0} Q (DefiKernel.Nary.Machine B P A D)
                            (@DefiKernel.Nary.advanceMonitored B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 Q
                              cfg boundaries branches update entry b))

∀ {B P A D : Type} [DecidableEq.{1} B] [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D]
