∀ {B P A D : Type} [DecidableEq.{1} B] [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D]
  (attempt : DefiKernel.Nary.Attempt B P A D) (result : DefiKernel.Composition.StepResult P A D),
