∀ {P A D : Type} [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D]
  (branches : DefiKernel.Nary.Branches DefiKernel.Parallel.BranchId P A D)
  (schedule : DefiKernel.Nary.Schedule DefiKernel.Parallel.BranchId)
  (mismatch : DefiKernel.Nary.ScheduleMismatch DefiKernel.Parallel.BranchId),
  @Eq.{1} DefiKernel.Interleaving.ScheduleMismatch
    (@DefiKernel.Nary.projectScheduleMismatch P A D branches schedule mismatch)
    {
      expectedLeft :=
        @List.length.{0} (DefiKernel.Composition.Invocation P A D) (branches DefiKernel.Parallel.BranchId.left),
      observedLeft :=
        @List.count.{0} DefiKernel.Parallel.BranchId
          (@instBEqOfDecidableEq.{0} DefiKernel.Parallel.BranchId DefiKernel.Parallel.instDecidableEqBranchId)
          DefiKernel.Parallel.BranchId.left schedule,
      expectedRight :=
        @List.length.{0} (DefiKernel.Composition.Invocation P A D) (branches DefiKernel.Parallel.BranchId.right),
      observedRight :=
        @List.count.{0} DefiKernel.Parallel.BranchId
          (@instBEqOfDecidableEq.{0} DefiKernel.Parallel.BranchId DefiKernel.Parallel.instDecidableEqBranchId)
          DefiKernel.Parallel.BranchId.right schedule }

