∀ {P A D : Type} [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D]
  (boundaries : DefiKernel.Nary.Boundaries DefiKernel.Parallel.BranchId P A D),
  @Eq.{1} (DefiKernel.Parallel.ParallelBoundary P A D) (@DefiKernel.Nary.toBinaryBoundaries P A D boundaries) boundaries

∀ {P A D : Type} [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D]
  (m : DefiKernel.Nary.Machine DefiKernel.Parallel.BranchId P A D) (world : DefiKernel.Composition.World P A D)
  (attempts : List.{0} (DefiKernel.Nary.Attempt DefiKernel.Parallel.BranchId P A D)),
  @Eq.{1} (DefiKernel.Interleaving.Machine P A D)
    (@DefiKernel.Nary.toBinaryMachine P A D
      (@DefiKernel.Nary.Machine.mk DefiKernel.Parallel.BranchId P A D world
        (@DefiKernel.Nary.Machine.locals DefiKernel.Parallel.BranchId P A D m) attempts))
    (have __src := @DefiKernel.Nary.toBinaryMachine P A D m;
    @DefiKernel.Interleaving.Machine.mk P A D world (@DefiKernel.Interleaving.Machine.left P A D __src)
      (@DefiKernel.Interleaving.Machine.right P A D __src) (@DefiKernel.Nary.toBinaryAttempts P A D attempts))

