  (∀ (cell : DefiKernel.Typed.Cell P A D),
      @Eq.{1} Rat (@DefiKernel.Typed.State.balance P A D (@DefiKernel.Typed.ExecutionResult.state P A D left) cell)
        (@DefiKernel.Typed.State.balance P A D (@DefiKernel.Typed.ExecutionResult.state P A D right) cell)) →
    @Eq.{1} (DefiKernel.Typed.CapabilityStore P A D) (@DefiKernel.Typed.ExecutionResult.capabilities P A D left)
        (@DefiKernel.Typed.ExecutionResult.capabilities P A D right) →
      @Eq.{1} (DefiKernel.Composition.World P A D) left right

∀ {B P A D : Type} [DecidableEq.{1} B] [DecidableEq.{1} P] [DecidableEq.{1} A] [DecidableEq.{1} D] [Fintype.{0} P]
  [Fintype.{0} A] [Fintype.{0} D] {branches : DefiKernel.Nary.Branches B P A D} {m : DefiKernel.Nary.Machine B P A D}
  {b : B},
  @Eq.{1} (Option.{0} (DefiKernel.Composition.LocatedFailure P A D))
      (@DefiKernel.Interleaving.LocalState.failure P A D (@DefiKernel.Nary.Machine.locals B P A D m b))
      (@Option.none.{0} (DefiKernel.Composition.LocatedFailure P A D)) →
    @Eq.{1} (Option.{0} (DefiKernel.Composition.Invocation P A D))
        (@GetElem?.getElem?.{0, 0, 0} (DefiKernel.Parallel.Branch P A D) Nat (DefiKernel.Composition.Invocation P A D)
          (fun (as : List.{0} (DefiKernel.Composition.Invocation P A D)) (i : Nat) =>
            @LT.lt.{0} Nat instLTNat i (@List.length.{0} (DefiKernel.Composition.Invocation P A D) as))
          (@List.instGetElem?NatLtLength.{0} (DefiKernel.Composition.Invocation P A D)) (branches b)
          (@DefiKernel.Interleaving.LocalState.consumed P A D (@DefiKernel.Nary.Machine.locals B P A D m b)))
        (@Option.none.{0} (DefiKernel.Composition.Invocation P A D)) →
      @DefiKernel.Nary.skippedToken B P A D branches m b

