theorem AdvanceSound.accounting {cfg : Config P A D} {boundaries : Boundaries B P A D}
    {branches : Branches B P A D} {m post : Machine B P A D} {b : B}
    (h : AdvanceSound cfg boundaries branches m b post) (d : D) (a : A) :
    total post.world.state d a - total m.world.state d a = post.supply d a - m.supply d a

theorem AdvanceSound.active_index {cfg : Config P A D}
    {boundaries : Boundaries B P A D} {branches : Branches B P A D}
    {m post : Machine B P A D} {b : B}
    (step : AdvanceSound cfg boundaries branches m b post)
    (previous : ∀ own, (m.locals own).failure = none →
      (m.locals own).nextIndex = min (m.locals own).consumed (branches own).length) :
    ∀ own, (post.locals own).failure = none →
      (post.locals own).nextIndex = min (post.locals own).consumed (branches own).length

