∀ {B P A D : Type} [inst : DecidableEq.{1} B] [inst_1 : DecidableEq.{1} P] [inst_2 : DecidableEq.{1} A]
  [inst_3 : DecidableEq.{1} D] [inst_4 : Fintype.{0} P] [inst_5 : Fintype.{0} A] [inst_6 : Fintype.{0} D]
  {cfg : DefiKernel.Composition.Config P A D} {boundaries : DefiKernel.Nary.Boundaries B P A D}
  {branches : DefiKernel.Nary.Branches B P A D} {m post : DefiKernel.Nary.Machine B P A D} {b : B},
  @DefiKernel.Nary.AdvanceSound B P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 inst_6 cfg boundaries branches m b
      post →
    (∀ (attempt : DefiKernel.Nary.Attempt B P A D),
        @Membership.mem.{0, 0} (DefiKernel.Nary.Attempt B P A D) (List.{0} (DefiKernel.Nary.Attempt B P A D))
